CREATE TABLE `attendance` (
  `attendance_id` int unsigned NOT NULL AUTO_INCREMENT,
  `student_id` int unsigned NOT NULL,
  `teacher_id` int unsigned NOT NULL,
  `qr_session_id` int unsigned DEFAULT NULL,
  `date` date NOT NULL,
  `time` time NOT NULL,
  `subject` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('present','tardy','absent') COLLATE utf8mb4_unicode_ci NOT NULL,
  `schedule_date` date NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`attendance_id`),
  UNIQUE KEY `uq_attendance_student_date_subject` (`student_id`,`date`,`subject`),
  KEY `idx_attendance_student_id` (`student_id`),
  KEY `idx_attendance_teacher_id` (`teacher_id`),
  KEY `idx_attendance_date` (`date`),
  KEY `idx_attendance_subject` (`subject`),
  KEY `idx_attendance_status` (`status`),
  KEY `idx_attendance_schedule_date` (`schedule_date`),
  KEY `idx_attendance_qr_session_id` (`qr_session_id`),
  KEY `idx_attendance_t_d_s` (`teacher_id`,`date`,`status`),
  KEY `idx_attendance_st_t_d` (`student_id`,`teacher_id`,`date`),
  KEY `idx_attendance_qr_sess` (`qr_session_id`,`teacher_id`),
  CONSTRAINT `fk_attendance_qr_session` FOREIGN KEY (`qr_session_id`) REFERENCES `qr_sessions` (`qr_session_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_attendance_student` FOREIGN KEY (`student_id`) REFERENCES `users` (`user_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_attendance_teacher` FOREIGN KEY (`teacher_id`) REFERENCES `users` (`user_id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3926 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

select `railway`.`attendance`.`attendance_id` AS `attendance_id`,`railway`.`attendance`.`student_id` AS `student_id`,`railway`.`attendance`.`teacher_id` AS `teacher_id`,`railway`.`attendance`.`qr_session_id` AS `qr_session_id`,`railway`.`attendance`.`date` AS `attendance_date`,`railway`.`attendance`.`date` AS `record_date`,`railway`.`attendance`.`time` AS `entry_time`,`railway`.`attendance`.`subject` AS `subject`,`railway`.`attendance`.`status` AS `status`,`railway`.`attendance`.`created_at` AS `created_at`,`railway`.`attendance`.`updated_at` AS `updated_at` from `railway`.`attendance`;

