select cast(`a`.`attendance_date` as date) AS `day`,count(0) AS `total_records`,sum((`a`.`status` = 'present')) AS `present_count`,sum((`a`.`status` = 'absent')) AS `absent_count`,sum((`a`.`status` = 'tardy')) AS `tardy_count` from (select `railway`.`attendance`.`date` AS `attendance_date`,`railway`.`attendance`.`status` AS `status` from `railway`.`attendance`) `a` group by cast(`a`.`attendance_date` as date);


